        <thead>
          <tr>
            <th style="width: 8%;">#</th>
            <th style="width: 28%;">Section / Page</th>
            <th style="width: 18%;">Status</th>
            <th>Description of Changes</th>
          </tr>
        </thead>
        <tbody>
